+      const channel = 'dm:user:u-1:beta@dev-mac-1';
+      final ciphertext = await hubSealFanet1(
+        senderDhKeyPair: userKey,
+        recipientDhPubkey: await betaKey!.keyPair.extractPublicKey(),
